import{_ as o}from"./chunks/notifikace_okno.BKxbiXUu.js";import{_ as a,o as n,c as t,aa as i}from"./chunks/framework.BAs_AphD.js";const l="/buildary-help-preview/media/cs/tickets/nastaveni_notifikace.png",h=JSON.parse('{"title":"Upozornění na úkoly","description":"","frontmatter":{"title":"Upozornění na úkoly","wiki":"cs:tickets:notification"},"headers":[],"relativePath":"tickets/notification.md","filePath":"tickets/notification.md","lastUpdated":1794209661000}'),r={name:"tickets/notification.md"};function s(d,e,k,m,p,v){return n(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="upozorneni-na-ukoly" tabindex="-1">Upozornění na úkoly <a class="header-anchor" href="#upozorneni-na-ukoly" aria-label="Permalink to &quot;Upozornění na úkoly&quot;">​</a></h1><p>Když někdo založí nebo změní úkol, který se vás týká, Buildary vám dá vědět: notifikací ve webové aplikaci, e-mailem a v mobilní aplikaci oznámením v telefonu. Tato stránka popisuje všechny tři cesty a kde se nastavují.</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/notifikace-mobil">Nastavit upozornění a zadávat úkoly z mobilu</a> v Akademii.</p><h2 id="komu-upozorneni-chodi" tabindex="-1">Komu upozornění chodí <a class="header-anchor" href="#komu-upozorneni-chodi" aria-label="Permalink to &quot;Komu upozornění chodí&quot;">​</a></h2><p>Upozornění dostávají lidé, kteří k úkolu mají vztah: Zadavatel úkolu, Řešitelé a Schvalovatelé. Kdo změnu udělal, upozornění o ní nedostane.</p><p>O úkolech, se kterými nemáte nic společného, upozornění nechodí, ani když je vidíte v seznamu.</p><h2 id="notifikace-ve-webove-aplikaci" tabindex="-1">Notifikace ve webové aplikaci <a class="header-anchor" href="#notifikace-ve-webove-aplikaci" aria-label="Permalink to &quot;Notifikace ve webové aplikaci&quot;">​</a></h2><p>Notifikace najdete pod zvonečkem v horní liště. Červené číslo u zvonečku ukazuje, kolik nových notifikací máte.</p><figure class="shot" style="--w:560px;"><img src="'+o+'" alt="Otevřené notifikace pod zvonečkem: nové úkoly, úpravy úkolů a vyjádření seskupené podle stavby" loading="lazy"></figure><p>Klikněte na zvoneček a otevře se seznam změn seskupený podle staveb: kdo co udělal, u kterého úkolu a kdy. Z notifikace přejdete rovnou na úkol. Volbou <strong>Označit vše jako přečtené</strong> notifikace odbavíte najednou, <strong>Zobrazit všechna oznámení</strong> otevře jejich úplný seznam.</p><p>Pod zvonečkem se objevují i upozornění ze Stavebního deníku, například na nepodepsaný záznam nebo potíže s elektronickým podpisem – viz <a href="/buildary-help-preview/firstofall/description">Orientace v aplikaci</a>.</p><h2 id="e-mailova-oznameni" tabindex="-1">E-mailová oznámení <a class="header-anchor" href="#e-mailova-oznameni" aria-label="Permalink to &quot;E-mailová oznámení&quot;">​</a></h2><p>E-maily o úkolech se nastavují každému členovi projektového týmu zvlášť. Bez nastavení e-maily nechodí – výchozí volba je <strong>žádné</strong>.</p><p>Nastavení najdete v <strong>Nastavení stavby</strong> → <strong>Projektový tým</strong> → <strong>Členové projektu</strong>: u člena klikněte na ikonu tužky a vyberte volbu v poli <strong>E-mailové oznámení - Management úkolů</strong>. Další e-mailová oznámení člena popisuje <a href="/buildary-help-preview/diary/projectteam">Projektový tým: firmy a lidé</a>.</p><figure class="shot" style="--w:440px;"><img src="'+l+'" alt="Pole E-mailové oznámení - Management úkolů s volbami žádné, HTML email, Email s událostí a Souhrnný email" loading="lazy"></figure><table tabindex="0"><thead><tr><th>Volba</th><th>Co chodí</th></tr></thead><tbody><tr><td><strong>žádné</strong></td><td>E-maily o úkolech nechodí.</td></tr><tr><td><strong>HTML email</strong></td><td>E-mail, když vznikne nový úkol, ve kterém jste Řešitel nebo Schvalovatel, a když k úkolu přibude vyjádření nebo komentář v diskuzi.</td></tr><tr><td><strong>Email s událostí</strong></td><td>E-mail o novém úkolu s událostí do kalendáře na den plánovaného konce. Když se změní plánovaný konec nebo se úkol smaže, přijde aktualizace.</td></tr><tr><td><strong>Souhrnný email</strong></td><td>Jednou denně jeden e-mail se všemi novými a změněnými úkoly, kterých se účastníte.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Mnoho úkolů?</p><p>Kdo řeší nebo schvaluje hodně úkolů, ocení <strong>Souhrnný email</strong> – místo desítek zpráv dostane jednu denně.</p></div><h2 id="oznameni-v-mobilni-aplikaci" tabindex="-1">Oznámení v mobilní aplikaci <a class="header-anchor" href="#oznameni-v-mobilni-aplikaci" aria-label="Permalink to &quot;Oznámení v mobilní aplikaci&quot;">​</a></h2><p>Máte-li v telefonu mobilní aplikaci Buildary (viz <a href="/buildary-help-preview/firstofall/mobile">Mobilní aplikace</a>), přijde vám oznámení přímo do telefonu – o novém úkolu, o změně úkolu i o novém záznamu ve stavebním deníku. Aplikaci kvůli tomu nemusíte mít otevřenou.</p><p>Pokud oznámení nechodí, zkontrolujte v nastavení telefonu, že má aplikace Buildary oznámení povolená.</p><p>Jak pracovat s úkoly v telefonu, popisuje <a href="/buildary-help-preview/tickets/m_task_grid">Úkoly v mobilu</a>.</p>',21)])])}const z=a(r,[["render",s]]);export{h as __pageData,z as default};
